; records.asm -- chapter 8: five records read through IX
; generated by gen08.py
        INCLUDE "msx.inc"
        OUTPUT "records.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
NAMES   EQU $1800                   ; the name table: one byte a cell
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld ix, objects
        ld b, 5
next:   ld a, (ix+0)            ; the address: low byte ...
        out (VDP_CTRL), a
        ld a, (ix+1)            ; ... and high byte,
        or $40                  ; with bit 6 set: a write
        out (VDP_CTRL), a
        ld a, (ix+2)            ; the character
        out (VDP_DATA), a
        out (VDP_DATA), a
        out (VDP_DATA), a       ; 3 cells: the VDP moves on by itself
        inc ix
        inc ix
        inc ix                  ; IX to the next record
        djnz next               ; five times (chapter 11)
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

objects:
        dw NAMES+3*32+3            ; object 1: its first cell
        db 2                       ; a filled box
        dw NAMES+5*32+20           ; object 2: its first cell
        db '#'                     ; its character
        dw NAMES+9*32+9            ; object 3: its first cell
        db 'X'                     ; its character
        dw NAMES+13*32+25          ; object 4: its first cell
        db '='                     ; its character
        dw NAMES+17*32+5           ; object 5: its first cell
        db 'O'                     ; its character
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
